import React, { useState } from 'react';

export default function ManageStudents() {
  const [searchTerm, setSearchTerm] = useState('');
  const [showAddForm, setShowAddForm] = useState(false);

  // Form Fields (යාළුවාගේ 5 වැනි පින්තූරේ තිබ්බ දත්ත ටික)
  const [regNumber, setRegNumber] = useState('');
  const [password, setPassword] = useState('');
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [address, setAddress] = useState('');
  const [course, setCourse] = useState('Primary Education');

  // ටෙස්ට් කරලා බලන්න දාපු sample සිසුන් ලැයිස්තුවක් (පස්සේ ඕන නම් Backend එකට කනෙක්ට් කරමු)
  const [students, setStudents] = useState([
    { regNo: 'HNCOE/PE/2026/01', name: 'Nimal Jayasinghe', email: 'nimal@gmail.com', phone: '0711234567', course: 'Primary Education' },
    { regNo: 'HNCOE/PE/2026/03', name: 'Kasun Perera', email: 'kasun@gmail.com', phone: '0779874563', course: 'Primary Education' }
  ]);

  const handleAddStudent = (e) => {
    e.preventDefault();
    const newStudent = {
      regNo: regNumber,
      name: fullName,
      email: email,
      phone: phone,
      course: course
    };
    setStudents([...students, newStudent]);
    alert("Student Registered Successfully!");
    setShowAddForm(false);
    
    // Form එක හිස් කිරීම
    setRegNumber(''); setPassword(''); setFullName('');
    setEmail(''); setPhone(''); setAddress('');
  };

  const filteredStudents = students.filter(s => 
    s.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.regNo.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div style={{ backgroundColor: '#fff', padding: '24px', borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.03)', height: '100%', display: 'flex', flexDirection: 'column', fontFamily: 'sans-serif' }}>
      
      {/* Upper Section */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
        <h2 style={{ margin: 0, color: '#1e293b', fontSize: '22px', fontWeight: '700' }}>Manage Students</h2>
        <button 
          onClick={() => setShowAddForm(!showAddForm)}
          style={{ backgroundColor: '#15803d', color: '#fff', border: 'none', padding: '10px 18px', borderRadius: '8px', fontWeight: '600', cursor: 'pointer' }}
        >
          {showAddForm ? '← Back to List' : '+ Add New Student'}
        </button>
      </div>

      {/* 1. Add New Student Form (යාළුවාගේ 5 වැනි පින්තූරේ පෙනුම ඔයාගේ කොළ පාට Theme එකට හැදුවා) */}
      {showAddForm ? (
        <div style={{ maxWidth: '600px', backgroundColor: '#f8fafc', padding: '25px', borderRadius: '12px', border: '1px solid #e2e8f0', overflowY: 'auto' }}>
          <h3 style={{ marginTop: 0, color: '#15803d', marginBottom: '20px' }}>🎓 Register New Student</h3>
          <form onSubmit={handleAddStudent} style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px' }}>
            
            <div>
              <label style={{ display: 'block', fontSize: '13px', fontWeight: '600', marginBottom: '5px' }}>Registration Number</label>
              <input type="text" required value={regNumber} onChange={(e) => setRegNumber(e.target.value)} placeholder="e.g. HNCOE/PE/2026/03" style={{ width: '100%', padding: '10px', borderRadius: '6px', border: '1px solid #cbd5e1', boxSizing: 'border-box' }} />
            </div>

            <div>
              <label style={{ display: 'block', fontSize: '13px', fontWeight: '600', marginBottom: '5px' }}>Temporary Password</label>
              <input type="password" required value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Enter secure password" style={{ width: '100%', padding: '10px', borderRadius: '6px', border: '1px solid #cbd5e1', boxSizing: 'border-box' }} />
            </div>

            <div style={{ gridColumn: '1 / span 2' }}>
              <label style={{ display: 'block', fontSize: '13px', fontWeight: '600', marginBottom: '5px' }}>Full Name</label>
              <input type="text" required value={fullName} onChange={(e) => setFullName(e.target.value)} placeholder="e.g. Kasun Perera" style={{ width: '100%', padding: '10px', borderRadius: '6px', border: '1px solid #cbd5e1', boxSizing: 'border-box' }} />
            </div>

            <div>
              <label style={{ display: 'block', fontSize: '13px', fontWeight: '600', marginBottom: '5px' }}>Email Address</label>
              <input type="email" required value={email} onChange={(e) => setEmail(e.target.value)} placeholder="e.g. student@gmail.com" style={{ width: '100%', padding: '10px', borderRadius: '6px', border: '1px solid #cbd5e1', boxSizing: 'border-box' }} />
            </div>

            <div>
              <label style={{ display: 'block', fontSize: '13px', fontWeight: '600', marginBottom: '5px' }}>Contact Number</label>
              <input type="text" required value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="e.g. 0771234567" style={{ width: '100%', padding: '10px', borderRadius: '6px', border: '1px solid #cbd5e1', boxSizing: 'border-box' }} />
            </div>

            <div style={{ gridColumn: '1 / span 2' }}>
              <label style={{ display: 'block', fontSize: '13px', fontWeight: '600', marginBottom: '5px' }}>Address</label>
              <input type="text" required value={address} onChange={(e) => setAddress(e.target.value)} placeholder="Enter residence address" style={{ width: '100%', padding: '10px', borderRadius: '6px', border: '1px solid #cbd5e1', boxSizing: 'border-box' }} />
            </div>

            <div style={{ gridColumn: '1 / span 2' }}>
              <label style={{ display: 'block', fontSize: '13px', fontWeight: '600', marginBottom: '5px' }}>Course</label>
              <select value={course} onChange={(e) => setCourse(e.target.value)} style={{ width: '100%', padding: '10px', borderRadius: '6px', border: '1px solid #cbd5e1', backgroundColor: '#fff' }}>
                <option value="Primary Education">Primary Education</option>
                <option value="Secondary Education">Secondary Education</option>
              </select>
            </div>

            <div style={{ gridColumn: '1 / span 2', marginTop: '10px' }}>
              <button type="submit" style={{ backgroundColor: '#15803d', color: '#fff', border: 'none', padding: '12px', borderRadius: '6px', fontWeight: '700', cursor: 'pointer', width: '100%' }}>
                Register Student
              </button>
            </div>
          </form>
        </div>
      ) : (
        // 2. Students List View
        <>
          {/* Search Bar */}
          <div style={{ marginBottom: '15px' }}>
            <input 
              type="text" 
              placeholder="🔍 Search by Registration No or Name..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              style={{ width: '100%', maxWidth: '400px', padding: '10px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', fontSize: '14px' }}
            />
          </div>

          {/* Student Table */}
          <div style={{ flex: 1, overflowY: 'auto', border: '1px solid #e2e8f0', borderRadius: '8px' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
              <thead>
                <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
                  <th style={{ padding: '12px 16px', fontSize: '13px', fontWeight: '700', color: '#1e293b' }}>Reg Number</th>
                  <th style={{ padding: '12px 16px', fontSize: '13px', fontWeight: '700', color: '#1e293b' }}>Full Name</th>
                  <th style={{ padding: '12px 16px', fontSize: '13px', fontWeight: '700', color: '#1e293b' }}>Course</th>
                  <th style={{ padding: '12px 16px', fontSize: '13px', fontWeight: '700', color: '#1e293b' }}>Email</th>
                  <th style={{ padding: '12px 16px', fontSize: '13px', fontWeight: '700', color: '#1e293b', textAlign: 'center' }}>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredStudents.length > 0 ? (
                  filteredStudents.map((student, index) => (
                    <tr key={index} style={{ borderBottom: '1px solid #f1f5f9', backgroundColor: index % 2 === 0 ? '#fff' : '#f8fafc' }}>
                      <td style={{ padding: '12px 16px', fontSize: '14px', color: '#15803d', fontWeight: '600' }}>{student.regNo}</td>
                      <td style={{ padding: '12px 16px', fontSize: '14px', color: '#334155', fontWeight: '500' }}>{student.name}</td>
                      <td style={{ padding: '12px 16px', fontSize: '14px', color: '#475569' }}>{student.course}</td>
                      <td style={{ padding: '12px 16px', fontSize: '14px', color: '#64748b' }}>{student.email}</td>
                      <td style={{ padding: '12px 16px', textAlign: 'center' }}>
                        <button style={{ background: 'none', border: 'none', color: '#2563eb', cursor: 'pointer', fontWeight: '600', marginRight: '10px' }}>✏️ Edit</button>
                        <button style={{ background: 'none', border: 'none', color: '#dc2626', cursor: 'pointer', fontWeight: '600' }}>🗑️ Delete</button>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="5" style={{ padding: '20px', textAlign: 'center', color: '#94a3b8', fontSize: '14px' }}>No students found.</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </>
      )}
    </div>
  );
}
